import React, { useMemo } from 'react';
import { formatDate } from '../utils/dateHelpers';
import { isDateInRange } from '../utils/dateHelpers';
import AvailabilityBadges from './AvailabilityBadges';

const CalendarCell = ({
  year,
  month,
  day,
  flightData,
  currentRoute,
  selectionRef,
  handleDateClick,
  cellPages,
  handlePageChange,
  // Filters
  classFilter,
  directFilter,
  sourceFilter,
  airlinesFilter,
  pointsFilter,
  // Helpers
  getEnrichedFlightData,
  activeTooltipRef
}) => {
  const dateString = formatDate(year, month, day);
  const isSelected = isDateInRange(dateString, selectionRef);

  // Get the flight data for this date
  const dateFlightData = useMemo(() => {
    if (!flightData?.dateMap || !dateString) return null;
    return flightData.dateMap[dateString] || null;
  }, [flightData, dateString]);

  // Get route segments to display
  const routeSegments = useMemo(() => {
    if (!currentRoute) return [];
    return Array.isArray(currentRoute) ? currentRoute : [currentRoute];
  }, [currentRoute]);

  // Determine classes to show
  const getClassesToShow = (classData) => {
    if (!classData) return [];

    // Classes to display based on filter
    const classes = classFilter.length > 0 ? classFilter : ['Y', 'W', 'J', 'F'];

    // Filter based on availability and other filters
    return classes.filter(classCode => {
      // Check if class is available
      const available = classData[`${classCode}Available`];
      if (!available) return false;

      // Apply direct filter
      if (directFilter && !classData[`${classCode}Direct`]) return false;

      return true;
    });
  };

  return (
    <div 
      className={`calendar-cell ${isSelected ? 'selected' : ''}`}
      onClick={() => handleDateClick(dateString)}
    >
      <div className="cell-date">{day}</div>

      <div className="cell-content">
        {routeSegments.map(route => {
          // Get flight data for this route on this date
          const routeData = dateFlightData?.[route];
          if (!routeData) return null;

          // Get classes to display
          const classesToShow = getClassesToShow(routeData);
          if (classesToShow.length === 0) return null;

          return (
            <div key={route} className="route-badges">
              <AvailabilityBadges
                route={route}
                dateString={dateString}
                classData={routeData}
                classesToShow={classesToShow}
                activeTooltipRef={activeTooltipRef}
                cellPages={cellPages}
                handlePageChange={handlePageChange}
                getEnrichedFlightData={getEnrichedFlightData}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CalendarCell;
